window.__W=window.__W||{};window.__W["Kanunnamei_Ali_Osman"]={"id":"Kanunnamei_Ali_Osman","title":"Kanunname-i Al-i Osman","pages":[{"n":"1–2","im":"page_1.jpg","w":1450,"h":1136,"R":[["text_column",722,295,1449,1072]],"L":[["text_column",[[722,295],[722,329],[758,331],[754,353],[754,377],[758,384],[769,386],[766,399],[743,400],[743,423],[775,424],[774,460],[756,462],[756,504],[747,506],[746,543],[765,544],[765,584],[772,586],[772,627],[778,629],[778,665],[745,668],[746,699],[755,703],[802,703],[804,750],[817,751],[817,767],[824,775],[822,780],[812,780],[814,992],[806,994],[806,1030],[814,1035],[814,1072],[1429,1072],[1431,1062],[1449,1062],[1449,1021],[1429,1019],[1431,1010],[1449,1010],[1449,987],[1429,985],[1429,936],[1431,927],[1439,927],[1439,904],[1429,903],[1429,826],[1426,799],[1419,783],[1418,462],[1415,453],[1418,342],[1415,336],[1320,336],[1304,333],[805,336],[801,333],[803,329],[818,329],[818,295]],"مورخین قديمهٔ عثمانیه آراسنده ایلك اول و یكانە اوله‌رق عالی افندی\nمرحوم طرفندن « كنه الاخبار » ده بيان اولنان سلطان محمد خان نانی\nقانوننامه‌سنك استانبول كتبخانه‌لرنده نسخه‌سی موجود اولمدیغندن ویاه\nكتبخانه ايچر طوپرسندن موجود بولنان نسخه‌سی فطوغرافيسنك اخذ\nایتدیريله‌رك ارسالی و یانە سفارت سنیسندن رجا اولنمش یدی . سفارت\nمشار الپهادن جواباً وارد اولان تحريراتده ذكر اولنان كتبخانه‌ده\nسلطان محمد خان نانی‌يه عائد اوله‌رق موجود اوچ عدد قانونامەدن\nایكنسك فطوغرافیلری ارسال ایدلیكی و دفترده ( قانون پادشاهی سلطان\nمحمد بن مراد خان ) ديه مقید اولان و ۸۹۳ سنهٔ هجریه‌سنده تحریر ايدلمش\nبولنان اوچنجیسك كتبخانه مأمورينندن دوقور قره‌ليچ جانبندن قريباً\nطبع و نشر اولنه‌جغی بیان اولنمشدر .\nاستمنجه فطوغرافيلری جلب اولنان منه كور ايچ قطعه قانوننامه‌دن\nبرنجیسی یدی و ایكنجیسی یكرمی درت كه جمعاً اوتوز بر پارچه یعنی\nبیوك صحیفه‌دن مركبدر . هر ایكنیسی ده دیوانی قیرمه‌سی خط ایله محرردر .\nيازيلری بريرندن فرقيدر . سطرلری ايسه بعضاً يكرمی سكز بعضاً\nاوتوز و اوتوزاوچ اولمق اوزره متفاوتدر . برنجیسنك ١٠٢٩ سنهٔ\nهجریه‌سنده تحرير اولنديغی نمايتنده بيان ايدلمش ايسه‌ده ايكنجیسنك\nتاریخ تحريری كوسترمامشدر .",0]]},{"n":"3–4","im":"page_2.jpg","w":1464,"h":1130,"R":[["header",1037,8,1174,42],["text_column",716,56,1463,917],["footnote",780,907,1463,1080],["page_number",1365,18,1383,38]],"L":[["header",[[1037,8],[1037,42],[1174,41],[1174,8]],"قانوننامه‌ٔ آل عثمان",0],["text_column",[[765,58],[764,102],[768,105],[769,161],[779,167],[775,170],[773,187],[767,191],[767,217],[771,222],[772,247],[777,247],[780,253],[807,253],[811,264],[769,266],[769,291],[750,293],[749,329],[753,329],[756,334],[738,339],[737,397],[769,397],[766,403],[760,404],[755,412],[751,412],[751,424],[741,426],[741,449],[761,449],[763,457],[746,458],[748,483],[746,486],[736,487],[732,499],[716,499],[716,659],[746,662],[741,671],[716,671],[716,725],[743,725],[747,733],[771,733],[775,767],[788,769],[785,785],[770,786],[771,822],[765,825],[763,876],[768,888],[793,889],[797,877],[820,878],[818,917],[1304,915],[1310,907],[1389,907],[1391,903],[1463,900],[1463,863],[1432,861],[1433,733],[1463,732],[1463,671],[1428,669],[1427,552],[1420,544],[1420,359],[1413,310],[1413,184],[1404,179],[1404,60],[1395,60],[1393,56],[1077,56],[946,64],[794,64],[791,57]],"زماننده اكمال ایدیلان مذكور قانون طبیعت ملیه‌مزك تكمالی و زمانك تأثیری\nجهتلرله بعد یدر تبدیل و تعیین كلدی‌یه دوجار اولمش و بو ده با الحاصه عدلی\nجهتده اجرا ایدلدیكی مستبان بولنمشدر .\nتأسیسات و تشكیلات دولتك اساسی محتوی اولان و پك یقین زمانلره\nقدر احكامی امور حكومته آژچوق تعمديلات ایله مرعی بولنان برنجی\nقانوننامه‌ده ایكی جهت شایان تدقیقدر : زمان تنظیممی و محری اولان\nتوفیقی ليس زادە بن مصطفی . بو ایكی جهتندن برنجیمی قانون نامەنك\nبعض محللرنده كوربلان قیودالرك تاریخنه تطبیقله حل ایدیجلكدر . بو\nصورتله زمان تنظيمی قطعی دكلسه : هر حالده طوغری‌يه قريب اوله‌رق\nبولنه‌جقدر . حالو كه محرری حقنده تاریخلرده بر كونه معلومات بولنه‌ميور .\nمكر كه زمان بوبابده شایان احتجاج و شریقه‌لر میدانە چیقاره و یا بعض یازمه\nمجوعه‌لرده معلومات لازم بولنه .\nبو قانوننامه سلطان محمد خان ثاینك او اخر سلطنتده تنظيم و تحرير\nایدلمشدر . زيرا قانونامه‌نك متنرده : حالبانیلدوكم مدارس عالیەیه صحن دیو\nاسم قولنمشدر » دیمسنه و بو مدارسك سلطان مشار الیه نامه منسوب\nجامع شریرفله بربر ٨۷٥ سنه هجرینه‌سنده رسیده‌دخ مدت اولدیغی تاریخلرده\nبیان ایده‌لسنه نظرأ تاریخ مذكوردن صوكره یازلدیغی ، ویربلان علوفهدن\nاوزمان قاضی‌سكرك بر اولدیغی آكلاتسمسنه [١] و خاقان مشار الیهك صوك\nصدر اعظمی اولان قره‌مانی محمد پاشا قاضیعسكرو بولنان مولی مصالح الدین\nمصطفی الفسطاطانی‌نك صالحندن و متكلم بالحق اولمسندن قوشقولا نه‌رق\nخاقان مشار الیهه وزرانك درت اولدیغی جهتنه قاضی‌سكرك دخی متعدد",1],["footnote",[[1463,907],[1309,907],[1304,916],[999,916],[929,925],[809,925],[805,917],[780,917],[780,999],[832,1001],[830,1025],[789,1025],[790,1073],[830,1073],[832,1080],[938,1079],[1049,1071],[1198,1068],[1217,1064],[1313,1059],[1463,1060]],"[١] متن قانون نامەده قاضی‌سكردكله‌سی بعضاً مفرد و بعضاً جمع اوله‌رق\nاستعمال اولنمشدر . علوه‌سنه نظر اوزمان قانون نامەده كوربلان دیكر سويلری مللو\nاولنمشی ای كلادیقندن مستحق متن قانون نامەده كوربلان دیكر سویلری مللو\nفرمانزما استقامدە قاضیه‌سكردلیك ایدی - بو كلمه‌يی ده بعض جمع اوله‌رق زیامدر .",2],["page_number",[[1365,18],[1365,38],[1383,36],[1383,18]],"٤",3]]}],"nw":16660,"nc":76747};